		},
		{
			in:  "(CWE-122|CWE-125)",
			out: []string{"CWE-122", "CWE-125"},
		},
	}

	r := RedHat{}
	for i, tt := range tests {
		out := r.parseCwe(tt.in)
		sort.Strings(out)
		sort.Strings(tt.out)
		if !reflect.DeepEqual(tt.out, out) {
			t.Errorf("[%d]expected: %s, actual: %s", i, tt.out, out)
		}
	}
}

